+    <div class="row g-2 mb-3">
+        <div class="col"><div class="card text-center p-2"><strong>Total</strong><span class="fs-5">@_allTasks.Count</span></div></div>
+        <div class="col"><div class="card text-center p-2"><strong>To Do</strong><span class="fs-5">@GetColumnTasks("To Do").Count</span></div></div>
+        <div class="col"><div class="card text-center p-2"><strong>In Progress</strong><span class="fs-5">@GetColumnTasks("In Progress").Count</span></div></div>
+        <div class="col"><div class="card text-center p-2"><strong>Done</strong><span class="fs-5">@GetColumnTasks("Done").Count</span></div></div>
+        <div class="col"><div class="card text-center p-2 @(OverdueCount > 0 ? "border-danger text-danger" : "")"><strong>Overdue</strong><span class="fs-5">@OverdueCount</span></div></div>
+    </div>
+
+    @* ── Search Bar ── *@
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title…"
+               @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    @* ── Kanban Columns ── *@
+    <div class="row g-3">
+        @foreach (var column in _columns)
+        {
+            var tasks = GetFilteredColumnTasks(column);
+            var colIndex = Array.IndexOf(_columns, column);
+
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@column</strong>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+                    <div class="card-body d-flex flex-column gap-2 overflow-auto" style="max-height:65vh;">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card shadow-sm">
+                                <div class="card-body p-2">
+                                    <h6 class="card-title mb-1">@task.Title</h6>
+                                    <p class="mb-1 text-muted small">@task.Assignee</p>
+                                    <div class="d-flex align-items-center gap-2 mb-1">
+                                        <span class="badge @PriorityBadgeClass(task.Priority)">@task.Priority</span>
+                                        <span class="small text-muted">@task.DueDate.ToString("MMM dd")</span>
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    disabled="@_operationInProgress"
+                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex - 1])">
+                                                ← Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < _columns.Length - 1)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    disabled="@_operationInProgress"
+                                                    @onclick="() => MoveTaskAsync(task.Id, _columns[colIndex + 1])">
+                                                Move Right →
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
+
+                    <div class="card-footer">
+                        @if (_addingToColumn == column)
+                        {
+                            <div class="d-flex flex-column gap-2">
+                                <input type="text" class="form-control form-control-sm" placeholder="Title"
+                                       @bind="_newTitle" />
+                                <input type="text" class="form-control form-control-sm" placeholder="Assignee"
+                                       @bind="_newAssignee" />
+                                <select class="form-select form-select-sm" @bind="_newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm" @bind="_newDueDate" />
+                                <div class="d-flex gap-1">
+                                    <button class="btn btn-primary btn-sm flex-fill"
+                                            disabled="@_operationInProgress"
+                                            @onclick="() => SaveNewTaskAsync(column)">Save</button>
+                                    <button class="btn btn-outline-secondary btn-sm flex-fill"
+                                            @onclick="CancelAdd">Cancel</button>
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-outline-primary btn-sm w-100"
+                                    @onclick="() => StartAdd(column)">+ Add Task</button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private string? _errorMessage;
+    private string _searchText = string.Empty;
+    private bool _operationInProgress;
+
+    // Add-task form state
+    private string? _addingToColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = "Medium";
+    private DateTime _newDueDate = DateTime.Today.AddDays(7);
+
+    private int OverdueCount => _allTasks.Count(t => t.DueDate < DateTime.Today && t.Status != "Done");
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadTasksAsync();
+    }
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _errorMessage = null;
+
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private List<TaskItem> GetColumnTasks(string status) =>
+        _allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredColumnTasks(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchText) ||
+                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _operationInProgress = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var task = _allTasks.First(t => t.Id == taskId);
+            _allTasks[_allTasks.IndexOf(task)] = task with { Status = newStatus };
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _operationInProgress = false;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        _addingToColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = "Medium";
+        _newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => _addingToColumn = null;
+
+    private async Task SaveNewTaskAsync(string column)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle))
+            return;
+
+        _operationInProgress = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
+            // If the service doesn't assign the correct status, adjust locally
+            var taskWithStatus = created.Status == column ? created : created with { Status = column };
+            _allTasks.Add(taskWithStatus);
+            _addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = ex.Message;
+        }
+        finally
+        {
+            _operationInProgress = false;
+        }
+    }
+
+    private static string PriorityBadgeClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+}
+

